 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_formatKeywrd_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        if(event.keyCode===13){$c.util.getComponent("ipt_pageIndex1").setValue(1);await scwin.tx_fn_searchList()}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75300.ipt_formatKeywrd_onkeydown' }); }
};

