///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchTaskExp
 * @description search Task Exp 처리
 * @param {*} ipt_integSrchNo ipt_integSrchNo
 * @returns {void}
 * @hidden N
 */
scwin.searchTaskExp = async function (ipt_integSrchNo) {
    $c.util.getComponent('ipt_pageIndex2').setValue("1");
    $c.util.getComponent('ipt_integSrchNo').setValue(ipt_integSrchNo);
    await scwin.openRelLaw(ipt_integSrchNo);
    if (!scwin.isLoad) {
        await scwin.tx_fn_searchRelLawDtl();
        scwin.isLoad = true;
    }
    $c.util.getComponent('editorArea').setStyle('display', 'block');
};

/**
 * @method
 * @name searchKeyRelLaw
 * @description search Key Rel Law 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchKeyRelLaw = async function () {
    if (event.keyCode === 13) {
        await scwin.tx_fn_searchRelLawDtl();
    }
};

/**
 * @method
 * @name moveRelLawList
 * @description move Rel Law List 처리
 * @returns {void}
 * @hidden N
 */
scwin.moveRelLawList = async function () {
    await scwin.tx_fn_searchRelLawDtl();
};

/**
 * @method
 * @name popRelLawDtl
 * @description pop Rel Law Dtl 처리
 * @param {*} relLawDtlNo relLawDtlNo
 * @returns {void}
 * @hidden N
 */
scwin.popRelLawDtl = function (relLawDtlNo) {
    const url = "/ods/integsrch.do?relLawDtlNo=" + relLawDtlNo + "&method=moveJsp&SCREN_ID=JLDSTF70020.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "단위조항 상세", width: "1200px", height: "800px" }, {});
};

/**
 * @method
 * @name click
 * @description click 처리
 * @param {*} relLawNo relLawNo
 * @param {*} outPutOrdNo outPutOrdNo
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.click = function (relLawNo, outPutOrdNo, index) {
    this.relLawNo = relLawNo;
    this.outputOrdNo = outPutOrdNo;
    this.index = index;
};

/**
 * @method
 * @name resetClick
 * @description reset Click 처리
 * @returns {void}
 * @hidden N
 */
scwin.resetClick = function () {
    this.relLawNo = "";
    this.outputOrdNo = "";
    this.index = "";
};

/**
 * @method
 * @name setKeywrd
 * @description set Keywrd 처리
 * @param {*} keywrd keywrd
 * @returns {void}
 * @hidden N
 */
scwin.setKeywrd = function (keywrd) {
    $c.util.getComponent('ipt_formatKeywrd').setValue(keywrd);
};

// [A] 초기 목록 미해결 — 진입 키 integsrch 를 쓰는 tx 가 7개다(tx_fn_searchList, tx_fn_openRelLaw, tx_fn_searchRelLawDtl, tx_fn_moveRelLaw)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name openRelLawDone
 * @description open Rel Law Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.openRelLawDone = function (data) {
    (($c.util.getComponent('relLawMappList')) && ($c.util.getComponent('relLawMappList')).removeAll ? ($c.util.getComponent('relLawMappList')).removeAll() : (($c.util.getComponent('relLawMappList')) && ($c.util.getComponent('relLawMappList')).setValue ? ($c.util.getComponent('relLawMappList')).setValue('') : void 0)).append(data);
    makeTableOdd();
};

/**
 * @method
 * @name openRelLaw
 * @description open Rel Law 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openRelLaw = async function () {
    const r = await scwin.tx_fn_openRelLaw();
    try {
        scwin.openRelLawDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldstf75300.fn_openRelLaw' });
    }
    return r;
};
